
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_8_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_8", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.938820878782347e+00, -4.841710825481598e+00, -4.705548423962599e+00, -4.516721099964643e+00, -4.258899637201549e+00, -3.914381649260298e+00, -3.467060742520044e+00, -2.906372601364684e+00, -2.230523128517757e+00, -1.478413239332423e+00, -8.590804256991016e-01, -6.246237965485379e-01, -6.245164040875475e-01, -5.302909738311404e-01, -3.587515938385323e-01, -1.926314268704097e-01, -8.301236482215810e-02, -2.738219964514165e-02, -5.881611884709818e-03, -6.623445449219239e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


